#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int cmp(const void *a, const void *b) {
    return (*(int*)a) - (*(int*)b);
}

int find_pos(int u, int v, int *start, int *adj) {
    int l = start[u];
    int r = start[u+1] - 1;
    while (l <= r) {
        int mid = l + (r - l) / 2;
        int val = adj[mid];
        if (val == v) return mid;
        if (val < v) l = mid + 1;
        else r = mid - 1;
    }
    return -1;
}

int main() {
    int N, M;
    scanf("%d %d", &N, &M);

    int *U = (int*)malloc(M * sizeof(int));
    int *V = (int*)malloc(M * sizeof(int));
    int *deg = (int*)calloc(N + 1, sizeof(int));

    for (int i = 0; i < M; i++) {
        scanf("%d %d", &U[i], &V[i]);
        deg[U[i]]++;
        deg[V[i]]++;
    }

    int *start = (int*)malloc((N + 2) * sizeof(int));
    start[1] = 0;
    for (int i = 1; i <= N; i++) {
        start[i+1] = start[i] + deg[i];
    }

    int total_edges = start[N+1];
    int *adj = (int*)malloc((total_edges + 5) * sizeof(int));
    int *cur = (int*)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) cur[i] = start[i];

    for (int i = 0; i < M; i++) {
        int u = U[i], v = V[i];
        adj[cur[u]++] = v;
        adj[cur[v]++] = u;
    }

    free(U); free(V); free(cur);

    for (int i = 1; i <= N; i++) {
        if (deg[i] > 1) {
            qsort(adj + start[i], deg[i], sizeof(int), cmp);
        }
    }

    int *g_val = (int*)calloc(total_edges + 5, sizeof(int));
    int *bestStart = (int*)calloc(N + 1, sizeof(int));
    int *ans = (int*)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) ans[i] = 1;

    for (int x = N; x >= 1; x--) {
        int l = start[x];
        int r = start[x+1];

        // Part 1: compute G[x,c] for c < x
        for (int pos = l; pos < r; pos++) {
            int c = adj[pos];
            if (c >= x) break;
            int val = 1 + bestStart[c];
            if (val < 2) val = 2;
            g_val[pos] = val;
            if (val > ans[x]) ans[x] = val;
        }

        // Part 2: compute G[c,x] for c < x
        int maxSuffix = 0;
        for (int pos = r - 1; pos >= l; pos--) {
            int c = adj[pos];
            if (c < x) {
                int val = 1 + maxSuffix;
                if (val < 2) val = 2;
                if (val > bestStart[c]) bestStart[c] = val;
                if (val > ans[c]) ans[c] = val;
                int p = find_pos(c, x, start, adj);
                g_val[p] = val;
            }
            int valXc = g_val[pos];
            if (valXc > maxSuffix) maxSuffix = valXc;
        }
    }

    for (int i = 1; i <= N; i++) {
        printf("%d", ans[i]);
        if (i < N) printf(" ");
    }
    printf("\n");

    free(start);
    free(adj);
    free(g_val);
    free(bestStart);
    free(ans);
    free(deg);

    return 0;
}
